const activityCatalog=[
{name:'A little of everything',icon:'✧',detail:'Miso wanders, reads, dances, and takes little breaks.'},
{name:'Walking around',icon:'👣',detail:'Exploring the room, one little paw at a time.'},
{name:'Reading',icon:'📖',detail:'Turning the pages of a favorite story.'},
{name:'Drinking water',icon:'💧',detail:'Lifting a glass for a refreshing sip.'},
{name:'Dancing',icon:'♫',detail:'Little steps, big ears, and a whole lot of joy.'},
{name:'Sleeping',icon:'☾',detail:'Curled up on the sofa for a cozy nap.'},
{name:'Eating together',icon:'🍽',detail:'Sharing the meal you chose.'}
];
const routine=['Walking around','Reading','Walking around','Drinking water','Dancing','Sleeping'];
function currentActivity(){if(activity==='A little of everything')return routine[Math.floor((Date.now()-activityStarted)/13000)%routine.length];if(activity==='Eating together'&&!state.sharedMeal)return'Reading';return activity}
function activityButtons(){return activityCatalog.filter(a=>!['A little of everything','Eating together'].includes(a.name)).map(a=>`<button data-act="${a.name}" title="${a.detail}" aria-label="${a.name}">${a.icon}<span>${a.name}</span></button>`).join('')}
function setActivity(name){if(!activityCatalog.some(a=>a.name===name))return;if(name==='Eating together'&&!state.sharedMeal){toast('Name your meal below, then share it with Miso.');return}activity=name;activityStarted=Date.now();if(page==='home'){drawRoom();document.querySelectorAll('[data-act]').forEach(b=>b.classList.toggle('selected',b.dataset.act===name))}}
function updateActionCaption(a){const meta=activityCatalog.find(x=>x.name===a)||{icon:'✧',detail:'A quiet moment, at your own pace.'};const title=$('#action-title'),detail=$('#action-detail'),icon=$('#action-icon');if(title)title.textContent=a==='Eating together'?'Eating '+state.sharedMeal.name:a==='Snacking'?'Miso is having a snack':'Miso is '+a.toLowerCase();if($('#room')?._misoPose?.travel&&a!=='Walking around'&&title)title.textContent='Walking over to '+(a==='Eating together'?'share your meal':a.toLowerCase());if(detail)detail.textContent=a==='Eating together'?'Taking little bites, just like you.':meta.detail;if(icon)icon.textContent=meta.icon;if(title)title.textContent=title.textContent.replaceAll('Miso',state.characterName)}
function openActivities(){showModal(`<div class="eyebrow">MISO’S EVERYDAY MOMENTS</div><h2>A whole little life.</h2><p>Pick an activity, or let Miso follow a little routine.</p><div class="activity-picker">${activityCatalog.map(a=>`<button class="${activity===a.name?'selected':''}" data-act="${a.name}"><b>${a.icon}</b><span>${a.name}<small>${a.detail}</small></span></button>`).join('')}</div>`)}
function bindWorldInteractions(){const canvas=$('#room');canvas.onclick=e=>{const rect=canvas.getBoundingClientRect(),x=(e.clientX-rect.left)*480/rect.width,y=(e.clientY-rect.top)*310/rect.height;if(x<115&&y>155)setActivity('Walking around');else if(x>350&&y>180)setActivity(state.sharedMeal?'Eating together':'Drinking water');else if(x>325&&y<175)setActivity('Reading');else if(x>150&&x<350&&y>170)setActivity('Sleeping');else setActivity('Walking around')};}
function isEligibleMealEvent(event,now=Date.now()){
// No live t:slim adapter is installed. Only explicit demo fixtures can be eligible here.
return !!event&&typeof event.id==='string'&&event.id.length>0&&event.source==='demo'&&event.kind==='meal_bolus'&&event.bolusDelivered===true&&Number.isFinite(event.carbs)&&event.carbs>0&&Number.isFinite(event.occurredAt)&&Number.isFinite(event.receivedAt)&&now-event.occurredAt>=0&&now-event.occurredAt<=600000&&now-event.receivedAt>=0&&now-event.receivedAt<=600000&&!state.usedMealEvents.includes(event.id);
}
function eligibleMealEvent(){return state.mealEvents.slice().reverse().find(e=>isEligibleMealEvent(e))||null}
function openEventSimulator(){showModal(`<div class="eyebrow">TEST ONLY · NO DEVICE ACTION</div><h2>Test the 10-minute gate.</h2><p>t:slim is not connected. These fixtures simulate read-only incoming events and never deliver insulin.</p><label class="field-label" for="event-kind">Incoming event</label><select id="event-kind"><option value="meal">Meal bolus delivered + carb entry</option><option value="correction">Correction bolus · no carbs</option><option value="carbs">Carb entry · no delivered bolus</option><option value="pending">Carbs + bolus requested · not delivered</option></select><label class="field-label" for="event-age">How long ago?</label><select id="event-age"><option value="0">Just now</option><option value="5">5 minutes ago</option><option value="11">11 minutes ago · should stay locked</option></select><div class="notice">One eligible event unlocks one timer. Old events, correction-only boluses, and carb-only entries stay locked.</div><div class="modal-actions"><button class="primary" id="receive-demo-event">Receive simulated event</button></div>`);$('#receive-demo-event').onclick=()=>{const kind=$('#event-kind').value,age=Number($('#event-age').value),time=Date.now()-age*60000;state.mealEvents=[{id:crypto.randomUUID(),source:'demo',kind:kind==='correction'?'correction_bolus':'meal_bolus',carbs:kind==='correction'?0:45,bolusDelivered:['meal','correction'].includes(kind),occurredAt:time,receivedAt:time}];save();modal.close();go('home');toast(eligibleMealEvent()?'Simulated meal event received. You can choose a timer.':'Simulated event received. It does not qualify for a timer.')};}
function mealCard(){return `<section class="card meal-card"><div class="meal-heading"><span class="meal-spark" aria-hidden="true">✦</span><div><div class="eyebrow">A LITTLE MEAL, TOGETHER</div><h2>What’s on your plate?</h2><p>Describe your dish, toppings, and sides. Miso will share a pixel-art version.</p></div><span class="ai-tag">LOCAL MEAL STUDIO</span></div><form id="meal-form" class="meal-input-row"><label class="sr-only" for="meal-name">Describe your meal</label><input id="meal-name" maxlength="120" placeholder="Chicken alfredo pasta, or salmon with rice and broccoli…" value="${escapeHTML(state.sharedMeal?.name||'')}" required><button class="primary" id="illustrate-meal">Illustrate my meal</button></form><div class="meal-examples">Try ${['Chicken alfredo pasta','Strawberry pancakes with whipped cream','Salmon with rice and broccoli'].map(n=>`<button data-meal-example="${n}">${n}</button>`).join('')}<button type="button" id="manual-meal">Choose a simple illustration myself</button></div><p id="meal-ai-status" class="meal-ai-status" role="status">Composed on your device from an illustrated ingredient library. Unsupported details are labeled. No nutrition or insulin estimates.</p><div id="food-learning" aria-live="polite"></div><div id="meal-result"></div>${state.sharedMeal?`<div class="shared-meal"><p>Miso’s plate: <b>${escapeHTML(state.sharedMeal.name)}</b><small>${escapeHTML(state.sharedMeal.recipe?.note||'Previously saved illustration; re-illustrate to add meal components.')}</small></p><button class="secondary" id="eat-again">Eat together</button>${window.DiaLearning.storySeen()?'<button class="text-link" id="replay-meal-story">Why does mealtime insulin matter?</button>':''}</div>`:''}</section>`}
let mealJob=0;
function bindMealCard(){
 const form=$('#meal-form');if(!form)return;const input=$('#meal-name');
 input.addEventListener('input',()=>{mealJob++;$('#meal-result').innerHTML='';$('#meal-ai-status').textContent='Ready to illustrate your description.';$('#illustrate-meal').disabled=false;$('#illustrate-meal').textContent='Illustrate my meal';window.DiaLearning.updateFood(input.value)});
 if(input.value.trim())window.DiaLearning.updateFood(input.value);
 const replay=$('#replay-meal-story');if(replay)replay.onclick=()=>window.DiaLearning.showStory();
 form.onsubmit=async e=>{e.preventDefault();const name=input.value.trim();if(!name)return;
  const job=++mealJob,button=$('#illustrate-meal'),status=$('#meal-ai-status');button.disabled=true;button.textContent='Composing…';form.setAttribute('aria-busy','true');$('#meal-result').innerHTML='';
  try{const result=await window.DiaMeals.match(name,message=>{if(job===mealJob&&page==='home')status.textContent=message});if(job!==mealJob||page!=='home')return;status.textContent=result.meal.note;mealResult(name,result.meal);}
  catch{if(job!==mealJob||page!=='home')return;$('#meal-result').innerHTML='';status.textContent='Your illustration could not be drawn. Your description is still here; try again.';}
  finally{form.removeAttribute('aria-busy');if(job===mealJob&&page==='home'){button.disabled=false;button.textContent='Illustrate my meal';}}
 };
 document.querySelectorAll('[data-meal-example]').forEach(b=>b.onclick=()=>{input.value=b.dataset.mealExample;window.DiaLearning.updateFood(input.value);form.requestSubmit()});
 $('#manual-meal').onclick=()=>{const name=input.value.trim();if(!name){input.focus();toast('Name your meal first.');return;}mealJob++;$('#illustrate-meal').disabled=false;$('#illustrate-meal').textContent='Illustrate my meal';$('#meal-ai-status').textContent='Optional manual choice. Your original description stays unchanged.';$('#meal-result').innerHTML=`<label class="field-label" for="meal-illustration">Simple illustration<select id="meal-illustration">${window.DiaMeals.foods.map(f=>`<option value="${f.id}">${f.name}</option>`).join('')}</select></label><button class="secondary" id="use-simple-meal">Preview my choice</button>`;$('#use-simple-meal').onclick=()=>{const select=$('#meal-illustration'),label=window.DiaMeals.foods.find(f=>f.id===select.value).name;const recipe=window.DiaMeals.parse(select.value==='custom'?'':label);Object.assign(recipe,{name,coverage:'manual',note:'You chose a simple '+label.toLowerCase()+' illustration. It does not show every detail of your description.'});mealResult(name,recipe);};};
 if($('#eat-again'))$('#eat-again').onclick=()=>setActivity('Eating together');
}
function mealResult(name,recipe){
 $('#meal-result').innerHTML=`<div class="meal-result-inner"><canvas id="meal-preview" width="300" height="200" aria-label="${escapeHTML(name)}. ${escapeHTML(recipe.note)}"></canvas><div><div class="eyebrow">${recipe.coverage==='manual'?'YOUR MANUAL ILLUSTRATION':recipe.coverage==='composed'?'COMPONENT ILLUSTRATION':recipe.coverage==='partial'?'PARTIAL ILLUSTRATION':'GENERIC PLATE'}</div><h3>${escapeHTML(name)}</h3><p>${escapeHTML(recipe.note)}</p><div class="meal-components">${recipe.components.map(id=>`<span>${escapeHTML(window.DiaMeals.labels[id]||id)}</span>`).join('')}</div><button class="primary" id="share-meal">Share this meal with Miso</button></div></div>`;
 const c=$('#meal-preview').getContext('2d');c.imageSmoothingEnabled=false;c.clearRect(0,0,300,200);c.save();c.translate(150,110);c.scale(3,3);window.DiaMealArt.render(c,recipe);c.restore();
 $('#share-meal').onclick=()=>{state.sharedMeal={name,food:recipe.base,recipe,matchedBy:recipe.coverage==='manual'?'manual':'local-components',createdAt:Date.now()};save();activity='Eating together';activityStarted=Date.now();home();window.DiaLearning.afterMeal();toast('Miso is joining you for '+name)};
}
